/**
 * Pre-fitted Per-Position Historical Point-Diff Models (`QB`, `RB`, `WR`, `TE`, `K`,
 * `DEF`, `lambda_pos = 75`), Curated Default (8 non-redundant systems), Ex-Ante
 * Train-Screened, and Pooled Reference (`lambda = 1`) weights across all 25 pure
 * astrological, divinatory, mystical, and witchcraft predictive systems (grouped
 * into 6 cosmic/divinatory categories, 194 discrete conditions) calibrated on
 * 36,163 Sleeper NFL regular-season player-games (2018-2026).
 *
 * Full methodology and empirical audit: docs/SLEEPER_POINT_DIFF_ANALYSIS.md
 */

export type PositionalModelPosition = 'QB' | 'RB' | 'WR' | 'TE' | 'K' | 'DEF';

export type PredictorSystemId =
  | 'team_synergy'
  | 'elemental_matchup'
  | 'planetary_synastry'
  | 'solar_lunar_transits'
  | 'witchcraft_sabbats_esbats'
  | 'medieval_geomancy'
  | 'runes_ogham'
  | 'kabbalah_gematria'
  | 'vedic_jyotish'
  | 'contest_horary'
  | 'secondary_progressions'
  | 'cosmobiology_midpoints'
  | 'annual_profections'
  | 'arabic_lots_manazil'
  | 'fixed_stars_parans'
  | 'egyptian_decans_modality'
  | 'bazi_wuxing'
  | 'rokuyo_tenchusatsu'
  | 'qimen_bagua'
  | 'hellenistic_planetary'
  | 'mayan_tzolkin'
  | 'greco_roman_onomancy'
  | 'biorhythms'
  | 'numerology'
  | 'oracular_archetypes';

export type PredictorCategoryId =
  | 'solar_zodiac_wheel'
  | 'lunar_fixed_stars'
  | 'team_elemental_chemistry'
  | 'planetary_orbits_timing'
  | 'numerology_name_lots'
  | 'sacred_day_calendars';

export type UsableSignalClass =
  | 'DYNAMIC_ESOTERIC_SIGNAL'
  | 'ELEMENTAL_HARMONY_SIGNAL'
  | 'CONFOUNDED_ESOTERIC_PROXY'
  | 'STATIC_NATAL_COHORT';

export interface PredictorCategoryMeta {
  readonly id: PredictorCategoryId;
  readonly label: string;
  readonly cosmicSource: string;
  readonly description: string;
  readonly systemIds: readonly PredictorSystemId[];
  readonly defaultSystemIds: readonly PredictorSystemId[];
}

export interface PredictorSystemMeta {
  readonly id: PredictorSystemId;
  readonly name: string;
  readonly shortName: string;
  readonly categoryId: PredictorCategoryId;
  readonly category: string;
  readonly subCategory: string;
  readonly defaultEnabled: boolean;
  readonly clusterBy: 'gameId' | 'gameDate' | 'playerId';
  readonly description: string;
  readonly sourceLabel: string;
  readonly sourceUrl: string;
  readonly conditionCount: number;
  readonly maxAbsRawDeltaPts: number;
  readonly maxAbsShrunkDeltaPts: number;
  readonly minPValue: number;
  readonly minQValue: number;
  readonly oosCorrelation: number;
  readonly oosTStat: number;
  readonly oosQuintileSpreadPts: number;
  readonly oosDecileSpreadPts: number;
}

export interface ConditionEmpiricalStat {
  readonly systemId: PredictorSystemId;
  readonly conditionId: string;
  readonly label: string;
  readonly sampleSize: number;
  readonly posAdjustedDelta: number;
  readonly withinPlayerDelta: number | null;
  readonly shrunkDelta: number;
  readonly clusterSe: number | null;
  readonly clusterTStat: number;
  readonly pValue: number;
  readonly qValue: number;
  readonly trainDelta: number | null;
  readonly oosDelta: number | null;
}

export interface UsableEsotericSignal {
  readonly featureKey: string;
  readonly systemId: PredictorSystemId;
  readonly systemName: string;
  readonly conditionId: string;
  readonly label: string;
  readonly signalClass: UsableSignalClass;
  readonly exAnteTrainSelected: boolean;
  readonly sampleSize: number;
  readonly posAdjustedDelta: number;
  readonly withinPlayerDelta: number | null;
  readonly shrunkDelta: number;
  readonly clusterTStat: number;
  readonly pValue: number;
  readonly qValue: number;
  readonly trainDelta: number | null;
  readonly oosDelta: number | null;
  readonly standaloneRidgeWeightPts: number | null;
  readonly jointRidgeWeightPts: number | null;
  readonly mechanismNote: string;
}

export interface RidgeFeatureWeight {
  readonly activationRate: number;
  readonly sampleSize: number;
  readonly ridgeWeight: number;
}

export interface FittedRidgeSubmodel {
  readonly ridgeLambda: number;
  readonly centeringIntercept: number;
  readonly weights: Readonly<Record<string, RidgeFeatureWeight>>;
}

export interface PositionalModelBundle {
  readonly position: PositionalModelPosition;
  readonly sampleSize: number;
  readonly ridgeLambda: number;
  readonly singleSystemLambda: number;
  readonly jointModel: FittedRidgeSubmodel;
  readonly defaultCuratedModel: FittedRidgeSubmodel | null;
  readonly trainScreenedModel: FittedRidgeSubmodel | null;
  readonly perSystemModels: Readonly<Record<PredictorSystemId, FittedRidgeSubmodel>>;
}

export interface SerializedPointDiffModelParameters {
  readonly ridgeLambda: number;
  readonly singleSystemLambda: number;
  readonly positionalRidgeLambda: number;
  readonly positionalSingleSystemLambda: number;
  readonly empiricalBayesKappa: number;
  readonly systemIds: readonly PredictorSystemId[];
  readonly defaultSystemIds: readonly PredictorSystemId[];
  readonly posMeanDiff: Readonly<Record<string, number>>;
  readonly jointModel: FittedRidgeSubmodel;
  readonly defaultCuratedModel: FittedRidgeSubmodel;
  readonly trainScreenedModel: FittedRidgeSubmodel;
  readonly perSystemModels: Readonly<Record<PredictorSystemId, FittedRidgeSubmodel>>;
  readonly positionalModels?: Readonly<Partial<Record<PositionalModelPosition, PositionalModelBundle>>>;
  readonly conditionStatsMap: Readonly<Record<string, ConditionEmpiricalStat>>;
}

